import React, { useEffect, useState, useCallback } from "react";
import { AdminUserService, AdminPolicyService, AdminKycService, AdminClaimService } from "../../lib/services";
import { extractErrorMessage } from "../../lib/api";
import ErrorAlert from "../../components/ui/ErrorAlert";
import { Skeleton } from "../../components/ui/Skeleton";
import { formatCurrency } from "../../lib/constants";
import Icon from "../../components/ui/Icon";

export default function AdminDashboard() {
  const [stats, setStats] = useState(null);
  const [error, setError] = useState("");

  const load = useCallback(async () => {
    setStats(null);
    setError("");
    try {
      const [users, policies, revenue, kyc, claims, payouts] = await Promise.all([
        AdminUserService.count().catch(() => ({ data: {} })),
        AdminPolicyService.count().catch(() => ({ data: {} })),
        AdminPolicyService.revenue().catch(() => ({ data: {} })),
        AdminKycService.count().catch(() => ({ data: {} })),
        AdminClaimService.count().catch(() => ({ data: {} })),
        AdminClaimService.payouts().catch(() => ({ data: {} })),
      ]);
      setStats({
        users: summarize(users.data),
        policies: summarize(policies.data),
        revenue: summarize(revenue.data),
        kyc: summarize(kyc.data),
        claims: summarize(claims.data),
        payouts: summarize(payouts.data),
      });
    } catch (err) {
      setError(extractErrorMessage(err, "Could not load admin dashboard."));
      setStats({});
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  return (
    <div className="space-y-8">
      <header>
        <p className="text-xs uppercase tracking-widest text-text-subtle">Administration</p>
        <h1 className="font-heading text-4xl font-semibold mt-1">Overview</h1>
        <p className="mt-2 text-text-muted">Operations snapshot across users, KYC, claims, and policy revenue.</p>
      </header>

      {error && <ErrorAlert message={error} onRetry={load} />}

      <div className="grid sm:grid-cols-2 xl:grid-cols-3 gap-4">
        <MetricCard title="Users" icon="users" value={stats?.users?.total} detail={stats?.users?.detail} />
        <MetricCard title="Policies" icon="file" value={stats?.policies?.total} detail={stats?.policies?.detail} />
        <MetricCard title="KYC" icon="shield" value={stats?.kyc?.total} detail={stats?.kyc?.detail} />
        <MetricCard title="Claims" icon="clipboard" value={stats?.claims?.total} detail={stats?.claims?.detail} />
        <MetricCard
          title="Revenue"
          icon="wallet"
          value={stats?.revenue ? formatMetricValue(stats.revenue.total, true) : undefined}
          detail={stats?.revenue?.detail}
        />
        <MetricCard
          title="Approved payouts"
          icon="wallet"
          value={stats?.payouts ? formatMetricValue(stats.payouts.total, true) : undefined}
          detail={stats?.payouts?.detail}
        />
      </div>
    </div>
  );
}

function summarize(data) {
  if (typeof data === "number") {
    return { total: data, detail: "" };
  }
  if (!data || typeof data !== "object") {
    return { total: 0, detail: "" };
  }
  const entries = Object.entries(data);
  const total = entries.reduce((sum, [, value]) => sum + Number(value || 0), 0);
  const detail = entries
    .map(([key, value]) => `${key}: ${value}`)
    .join(" · ");
  return {
    total: total || Number(entries[0]?.[1] || 0),
    detail,
  };
}

function formatMetricValue(value, asCurrency) {
  if (value === undefined) return undefined;
  return asCurrency ? formatCurrency(value) : value;
}

function MetricCard({ title, icon, value, detail }) {
  return (
    <div className="rounded-2xl border border-border bg-surface p-5">
      <div className="flex items-center justify-between">
        <p className="text-xs uppercase tracking-widest text-text-subtle">{title}</p>
        <Icon name={icon} className="text-text-muted" />
      </div>
      {value === undefined ? (
        <Skeleton className="h-8 w-20 mt-2" />
      ) : (
        <p className="font-heading text-3xl font-semibold mt-1">{value}</p>
      )}
      {detail ? <p className="mt-2 text-sm text-text-muted">{detail}</p> : null}
    </div>
  );
}
